/**
 * Distance & Travel Time Calculator
 *
 * Lets users pick any two of the 43 destinations in Puducherry / Auroville
 * and inspect real road distance & travel time for Walk, Cycle, Car, and Bus.
 *
 * Strictly loads /data/distances.json generated by OSRM routing.
 * Does NOT call Nominatim or OSRM from the browser.
 */

import React, { useState, useEffect, useRef } from 'react';
import { Footprints, Bike, Bus, Car, MapPin, ArrowRight, RotateCcw } from 'lucide-react';
import { PLACES } from '../../data/places.js';

// All 43 destinations
const PLACE_OPTIONS = [...PLACES].sort((a, b) => a.name.localeCompare(b.name));

function SearchableSelect({ label, value, onChange, exclude }) {
  const [query, setQuery] = useState('');
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  const filtered = PLACE_OPTIONS
    .filter(p => p.id !== exclude)
    .filter(p => p.name.toLowerCase().includes(query.toLowerCase()));

  const selected = PLACE_OPTIONS.find(p => p.id === value);

  // Close on outside click
  useEffect(() => {
    const handler = (e) => {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  return (
    <div ref={ref} className="relative w-full">
      <label className="block text-[11px] font-semibold text-slate-500 dark:text-slate-400 mb-1">
        {label}
      </label>
      <button
        type="button"
        onClick={() => { setOpen(o => !o); setQuery(''); }}
        className="w-full text-left px-3 py-2 rounded-xl bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white font-medium text-xs flex items-center justify-between gap-2 hover:border-teal-400 transition"
      >
        <span className={selected ? 'truncate' : 'text-slate-400'}>
          {selected ? selected.name : 'Select a place…'}
        </span>
        <MapPin className="w-3.5 h-3.5 shrink-0 text-slate-400" />
      </button>

      {open && (
        <div className="absolute z-30 mt-1.5 w-full rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 shadow-xl max-h-56 overflow-hidden flex flex-col">
          <div className="p-2 border-b border-slate-100 dark:border-slate-700">
            <input
              autoFocus
              type="text"
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search destination…"
              className="w-full px-2.5 py-1.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 text-xs text-slate-900 dark:text-white placeholder-slate-400 outline-none"
            />
          </div>
          <div className="overflow-y-auto">
            {filtered.length === 0 ? (
              <p className="text-xs text-slate-400 p-3 text-center">No matches found</p>
            ) : (
              filtered.map(p => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() => { onChange(p.id); setOpen(false); setQuery(''); }}
                  className={`w-full text-left px-3 py-2 text-xs hover:bg-teal-50 dark:hover:bg-teal-900/30 transition flex items-center gap-2 ${
                    p.id === value
                      ? 'bg-teal-50 dark:bg-teal-900/20 font-semibold text-teal-700 dark:text-teal-300'
                      : 'text-slate-800 dark:text-slate-200'
                  }`}
                >
                  <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-slate-100 dark:bg-slate-700 text-slate-500 dark:text-slate-400 shrink-0">
                    {p.category}
                  </span>
                  <span className="truncate">{p.name}</span>
                </button>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
}

function ModeRow({ icon, label, distanceKm, durationMin, badge, isWalkOver90, isEstimated }) {
  return (
    <div className="flex flex-col sm:flex-row sm:items-center justify-between py-2.5 border-b border-slate-100 dark:border-slate-800 last:border-0 gap-1.5">
      <div className="flex items-center gap-2.5">
        <div className="p-1.5 rounded-xl bg-slate-100 dark:bg-slate-800 shrink-0">{icon}</div>
        <span className="text-xs font-semibold text-slate-800 dark:text-slate-200 w-16 shrink-0">{label}</span>
        {badge && (
          <span className="text-[10px] px-2 py-0.5 rounded-full font-medium bg-amber-100 dark:bg-amber-950/60 text-amber-800 dark:text-amber-300">
            {badge}
          </span>
        )}
      </div>

      <div className="flex items-center gap-2 text-xs pl-8 sm:pl-0">
        {distanceKm != null ? (
          <>
            <span className="font-bold text-slate-900 dark:text-white">{distanceKm} km</span>
            <span className="text-slate-400">•</span>
            {isWalkOver90 ? (
              <span className="text-rose-600 dark:text-rose-400 font-bold bg-rose-50 dark:bg-rose-950/40 px-2 py-0.5 rounded-lg">
                Not recommended on foot ({Math.round(durationMin)} min)
              </span>
            ) : (
              <span className="text-slate-700 dark:text-slate-300 font-medium">
                {isEstimated ? `~${Math.round(durationMin)} min` : `${Math.round(durationMin)} min`}
              </span>
            )}
          </>
        ) : (
          <span className="text-slate-400">—</span>
        )}
      </div>
    </div>
  );
}

export default function DistanceCalculator() {
  const [fromId, setFromId] = useState('');
  const [toId, setToId] = useState('');
  const [matrix, setMatrix] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const fromPlace = PLACE_OPTIONS.find(p => p.id === fromId);
  const toPlace = PLACE_OPTIONS.find(p => p.id === toId);

  // Load distances.json via fetch on mount
  useEffect(() => {
    let isMounted = true;
    setIsLoading(true);

    fetch('/data/distances.json')
      .then(res => {
        if (!res.ok) throw new Error(`HTTP error ${res.status}`);
        return res.json();
      })
      .then(data => {
        if (isMounted) {
          setMatrix(data);
          setIsLoading(false);
        }
      })
      .catch(err => {
        console.warn('Could not fetch /data/distances.json, trying fallback', err);
        if (isMounted) {
          setIsLoading(false);
          setError('Could not load distances database. Ensure distances.json is available.');
        }
      });

    return () => { isMounted = false; };
  }, []);

  // Look up values for selected pair
  const pairData = React.useMemo(() => {
    if (!matrix || !fromPlace || !toPlace) return null;

    // Look up by exact name
    const lookup = matrix[fromPlace.name]?.[toPlace.name];
    if (lookup) return lookup;

    // Fallback search across names
    const fromKeys = Object.keys(matrix);
    const matchedFrom = fromKeys.find(k => k.toLowerCase().includes(fromPlace.name.toLowerCase().split('/')[0].trim()));
    if (matchedFrom) {
      const toKeys = Object.keys(matrix[matchedFrom]);
      const matchedTo = toKeys.find(k => k.toLowerCase().includes(toPlace.name.toLowerCase().split('/')[0].trim()));
      if (matchedTo) return matrix[matchedFrom][matchedTo];
    }

    return null;
  }, [matrix, fromPlace, toPlace]);

  const handleSwap = () => {
    setFromId(toId);
    setToId(fromId);
  };

  const handleReset = () => {
    setFromId('');
    setToId('');
  };

  return (
    <div className="space-y-4">
      {/* From / To dropdowns with search */}
      <div className="flex flex-col sm:flex-row items-start sm:items-end gap-3">
        <div className="flex-1 w-full">
          <SearchableSelect label="From Destination" value={fromId} onChange={setFromId} exclude={toId} />
        </div>

        <button
          type="button"
          onClick={handleSwap}
          disabled={!fromId && !toId}
          className="p-2 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800 transition mb-0.5 shrink-0 self-center sm:self-end disabled:opacity-40"
          title="Swap From and To"
        >
          <ArrowRight className="w-4 h-4" />
        </button>

        <div className="flex-1 w-full">
          <SearchableSelect label="To Destination" value={toId} onChange={setToId} exclude={fromId} />
        </div>

        {(fromId || toId) && (
          <button
            type="button"
            onClick={handleReset}
            className="p-2 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-400 hover:text-rose-500 hover:border-rose-300 transition mb-0.5 shrink-0"
            title="Reset selections"
          >
            <RotateCcw className="w-4 h-4" />
          </button>
        )}
      </div>

      {/* Loading state */}
      {isLoading && (
        <p className="text-xs text-slate-400 animate-pulse text-center py-2">
          Loading official Pondicherry distance matrix…
        </p>
      )}

      {/* Results Card */}
      {fromPlace && toPlace && (
        <div className="rounded-2xl border border-slate-200 dark:border-slate-700 bg-white/70 dark:bg-slate-800/50 divide-y divide-slate-100 dark:divide-slate-800 overflow-hidden shadow-sm">
          {/* Header */}
          <div className="px-4 py-2.5 flex items-center justify-between text-xs text-slate-500 dark:text-slate-400 bg-slate-50/80 dark:bg-slate-800/80">
            <div className="flex items-center gap-2 truncate">
              <span className="font-bold text-slate-800 dark:text-slate-200 truncate">{fromPlace.name}</span>
              <ArrowRight className="w-3.5 h-3.5 shrink-0 text-slate-400" />
              <span className="font-bold text-slate-800 dark:text-slate-200 truncate">{toPlace.name}</span>
            </div>
            <span className="text-[10px] px-2 py-0.5 rounded-full font-medium bg-teal-100 text-teal-800 dark:bg-teal-900/60 dark:text-teal-300 shrink-0 ml-2">
              OSRM Real Route
            </span>
          </div>

          {/* Mode rows */}
          <div className="px-4 py-1">
            <ModeRow
              icon={<Footprints className="w-3.5 h-3.5 text-emerald-600" />}
              label="Walk"
              distanceKm={pairData?.foot_km}
              durationMin={pairData?.foot_min}
              isWalkOver90={pairData?.foot_min != null && pairData.foot_min > 90}
            />
            <ModeRow
              icon={<Bike className="w-3.5 h-3.5 text-teal-600" />}
              label="Cycle"
              distanceKm={pairData?.bike_km}
              durationMin={pairData?.bike_min}
            />
            <ModeRow
              icon={<Car className="w-3.5 h-3.5 text-rose-600" />}
              label="Car"
              distanceKm={pairData?.car_km}
              durationMin={pairData?.car_min}
            />
            <ModeRow
              icon={<Bus className="w-3.5 h-3.5 text-blue-600" />}
              label="Bus"
              distanceKm={pairData?.car_km}
              durationMin={pairData?.bus_min_estimate}
              badge="Estimated"
              isEstimated={true}
            />
          </div>

          {error && (
            <div className="px-4 py-2 text-xs text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/30">
              {error}
            </div>
          )}
        </div>
      )}

      {!fromPlace && !toPlace && (
        <p className="text-xs text-slate-400 text-center py-1">
          Select From and To destinations above to view real road distance and travel time.
        </p>
      )}
    </div>
  );
}
